/**
 * test-auditor-falsification.js - Independent Forensic Anti-Cheat Falsification Script
 * auditor_m2_gen2 - Milestone 2 Iteration 2
 *
 * Verifies that all 7 remediations in app/js/app.js are genuine, general-purpose
 * algorithmic logic and cannot be fooled by adversarial counter-examples.
 */

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// Resolve JSDOM across available environments
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      throw new Error('JSDOM module could not be resolved: ' + e.message);
    }
  }
}

const htmlPath = path.resolve('/home/prem/webos-projects/cinejoy-webos/app/index.html');
const configPath = path.resolve('/home/prem/webos-projects/cinejoy-webos/app/js/config.js');
const appPath = path.resolve('/home/prem/webos-projects/cinejoy-webos/app/js/app.js');

function createFreshApp(initialHash = '#home') {
  const html = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(html, {
    url: 'http://localhost/' + initialHash,
    runScripts: 'outside-only'
  });
  const { window } = dom;
  if (!window.Element.prototype.scrollIntoView) {
    window.Element.prototype.scrollIntoView = function () {};
  }
  const configCode = fs.readFileSync(configPath, 'utf8');
  const appCode = fs.readFileSync(appPath, 'utf8');
  window.eval(configCode);
  window.eval(appCode);
  return { dom, window, app: window.CinejoyApp };
}

let checksPassed = 0;
let checksTotal = 0;

function runCheck(name, fn) {
  checksTotal++;
  process.stdout.write(`  [Auditor Check ${checksTotal}] ${name} ... `);
  try {
    fn();
    console.log('✔ PASS');
    checksPassed++;
  } catch (err) {
    console.log('✖ FAIL: ' + err.message);
    throw err;
  }
}

async function runAsyncCheck(name, fn) {
  checksTotal++;
  process.stdout.write(`  [Auditor Check ${checksTotal}] ${name} ... `);
  try {
    await fn();
    console.log('✔ PASS');
    checksPassed++;
  } catch (err) {
    console.log('✖ FAIL: ' + err.message);
    throw err;
  }
}

async function main() {
  console.log('===============================================================');
  console.log('auditor_m2_gen2: Independent Forensic Falsification Suite');
  console.log('===============================================================\n');

  // Check 1: Deep chain details navigation loop escape
  runCheck('Deep chain details navigation: details -> details -> details -> Back', () => {
    const { app } = createFreshApp();
    app.init();
    assert.strictEqual(app.state.currentView, 'home');

    // Simulate 5 consecutive detail views
    for (let i = 1; i <= 5; i++) {
      app.openDetails({ title: 'Movie ' + i, year: '202' + i, rating: '8.' + i });
      assert.strictEqual(app.state.currentView, 'details');
    }

    // Press Back
    app.handleBackNavigation();
    assert.strictEqual(app.state.currentView, 'home', 'Must escape to home, got ' + app.state.currentView);
  });

  // Check 2: Rapid asynchronous focus cancellation across 10 random transitions
  await runAsyncCheck('Random rapid view switches do not leave ghost focus in hidden views', async () => {
    const { window, app } = createFreshApp();
    app.init();

    const views = ['home', 'movies', 'series', 'search', 'details', 'player'];
    for (let i = 0; i < 15; i++) {
      const v = views[i % views.length];
      app.switchView(v);
      await new Promise(r => setTimeout(r, Math.floor(Math.random() * 30) + 5));
    }
    // Final settle
    app.switchView('movies');
    await new Promise(r => setTimeout(r, 80));

    const focused = app.state.focusedElement;
    assert.ok(focused, 'A focused element must exist');
    const moviesView = window.document.getElementById('view-movies');
    const header = window.document.querySelector('.app-header');
    const isValid = moviesView.contains(focused) || header.contains(focused);
    assert.ok(isValid, 'Focused element must be inside active view or header');
  });

  // Check 3: Focus retention under immediate manual navigation
  await runAsyncCheck('Manual user selection in new view is preserved over delayed focus timer', async () => {
    const { window, app } = createFreshApp();
    app.init();

    app.switchView('series');
    await new Promise(r => setTimeout(r, 15));

    // User navigates to 2nd card
    const cards = window.document.getElementById('view-series').querySelectorAll('.card-poster');
    assert.ok(cards.length > 2, 'Must have cards in series view');
    const targetCard = cards[2];
    app.setFocus(targetCard);
    assert.strictEqual(app.state.focusedElement, targetCard);

    // Wait past the 50ms timer
    await new Promise(r => setTimeout(r, 60));

    // Verify focus was NOT hijacked
    assert.strictEqual(app.state.focusedElement, targetCard, 'Focus should stay on user-selected card');
  });

  // Check 4: Type fuzzing and hostile input safety on updateSearchResults
  runCheck('Hostile input fuzzing on updateSearchResults does not crash', () => {
    const { app } = createFreshApp('#search');
    app.init();

    const hostileInputs = [
      null,
      undefined,
      0,
      -1,
      12345,
      NaN,
      Infinity,
      -Infinity,
      true,
      false,
      [],
      [1, 2, 'abc'],
      {},
      { foo: 'bar' },
      { toString: () => { throw new Error('Hostile toString'); } },
      new Date(),
      /regex/,
      () => {},
      '',
      '   ',
      '\t\r\n',
      'Dune'
    ];

    for (const input of hostileInputs) {
      assert.doesNotThrow(() => {
        app.updateSearchResults(input);
      }, `Failed on input: ${typeof input}`);
    }
  });

  // Check 5: Defensive navigateSpatial with malformed or missing event objects
  runCheck('Defensive navigateSpatial with malformed/missing events', () => {
    const { window, app } = createFreshApp();
    app.init();

    const navs = window.document.querySelectorAll('[data-nav="true"]');
    navs[0].getBoundingClientRect = () => ({ top: 0, bottom: 30, left: 0, right: 50, width: 50, height: 30 });
    navs[1].getBoundingClientRect = () => ({ top: 0, bottom: 30, left: 60, right: 120, width: 60, height: 30 });
    app.setFocus(navs[0]);

    // Test missing event
    assert.doesNotThrow(() => app.navigateSpatial('ArrowRight'));
    // Test empty event
    assert.doesNotThrow(() => app.navigateSpatial('ArrowRight', {}));
    // Test event with non-function preventDefault
    assert.doesNotThrow(() => app.navigateSpatial('ArrowRight', { preventDefault: null }));
    assert.doesNotThrow(() => app.navigateSpatial('ArrowRight', { preventDefault: 42 }));
    assert.doesNotThrow(() => app.navigateSpatial('ArrowRight', { preventDefault: 'string' }));
  });

  // Check 6: Init idempotency with 10 re-invocations
  runCheck('CinejoyApp.init() idempotency stress test (10 calls)', () => {
    const { window, app } = createFreshApp('#search');
    for (let i = 0; i < 10; i++) {
      app.init();
    }
    assert.strictEqual(app.state.initialized, true);

    const keyB = window.document.querySelector('[data-key="B"]');
    assert.ok(keyB, 'Key B must exist on virtual keyboard');
    keyB.dispatchEvent(new window.MouseEvent('click', { bubbles: true }));

    assert.strictEqual(app.state.searchQuery, 'B', 'Query must have exactly 1 B, not duplicated');
  });

  // Check 7: Detached DOM element spatial navigation recovery
  runCheck('Focus recovery when active element is detached from document', () => {
    const { window, app } = createFreshApp();
    app.init();

    const ephemeralBtn = window.document.createElement('button');
    ephemeralBtn.setAttribute('data-nav', 'true');
    window.document.body.appendChild(ephemeralBtn);
    app.setFocus(ephemeralBtn);

    assert.strictEqual(app.state.focusedElement, ephemeralBtn);

    // Remove from DOM
    ephemeralBtn.remove();
    assert.strictEqual(window.document.body.contains(ephemeralBtn), false);

    // Navigate
    app.navigateSpatial('ArrowDown', { preventDefault: () => {} });

    // Focused element must have recovered to an attached element
    assert.notStrictEqual(app.state.focusedElement, ephemeralBtn);
    assert.ok(app.state.focusedElement, 'A focused element must exist after recovery');
    assert.strictEqual(window.document.body.contains(app.state.focusedElement), true, 'Recovered focus element must be inside document.body');
  });

  // Check 8: AST and code anti-cheat analysis on app/js/app.js
  runCheck('Anti-cheat source code inspection: no hardcoded test branches or bypasses', () => {
    const code = fs.readFileSync(appPath, 'utf8');

    // Forbidden patterns:
    const forbiddenPatterns = [
      /if\s*\([^)]*adversarial[^)]*\)/i,
      /if\s*\([^)]*test\s*===/i,
      /if\s*\([^)]*test\s*==/i,
      /if\s*\([^)]*__XSS_PWNED/i,
      /if\s*\([^)]*__IMG_PWNED/i,
      /if\s*\([^)]*Shōgun/i,
      /if\s*\([^)]*Shogun/i,
      /if\s*\([^)]*Item 1/i,
      /if\s*\([^)]*Item 2/i,
      /if\s*\([^)]*mock/i,
      /return\s+(true|false|0|1)\s*;\s*\/\/\s*bypass/i
    ];

    for (const pat of forbiddenPatterns) {
      assert.ok(!pat.test(code), 'Forbidden anti-cheat bypass pattern detected: ' + pat);
    }
  });

  console.log(`\n===============================================================`);
  console.log(`Auditor Falsification Results: ${checksPassed}/${checksTotal} checks PASSED (100%)`);
  console.log('===============================================================\n');
}

main().catch(err => {
  console.error('Auditor falsification suite failed:', err);
  process.exit(1);
});
